#!/usr/bin/env python3
"""Fetch each asset in the manifest from the dev server and write the bundle."""
import os
import sys
import time
import urllib.error
import urllib.request

# Connection resets from the dev server are transient (the server drops one
# connection per build run, and which one varies by run). Retry dropped
# connections a few times before giving up on an asset. HTTP errors (4xx/5xx)
# are not transient and are surfaced immediately.
FETCH_ATTEMPTS = 5
RETRY_DELAY_SECONDS = 0.25


def _connect_error(exc):
    """True for connection-level errors worth retrying (drops, resets)."""
    if isinstance(exc, urllib.error.HTTPError):
        return False
    if isinstance(exc, (ConnectionError, TimeoutError, OSError)):
        return True
    # http.client.HTTPException covers 'Remote end closed connection'
    # and 'Connection reset by peer' reported through the HTTP layer.
    return isinstance(exc, Exception) and exc.__class__.__name__.startswith("HTTP")


def fetch(port, path):
    url = "http://127.0.0.1:%s/%s" % (port, path)
    last_exc = None
    for attempt in range(1, FETCH_ATTEMPTS + 1):
        try:
            with urllib.request.urlopen(url, timeout=5) as resp:
                return resp.read()
        except Exception as exc:
            last_exc = exc
            if not _connect_error(exc):
                raise
            if attempt < FETCH_ATTEMPTS:
                time.sleep(RETRY_DELAY_SECONDS * attempt)
    raise last_exc


def main():
    port, manifest, outdir = sys.argv[1], sys.argv[2], sys.argv[3]
    os.makedirs(outdir, exist_ok=True)
    with open(manifest) as fh:
        names = [line.strip() for line in fh if line.strip()]
    try:
        index = fetch(port, "").decode()
    except Exception as exc:
        print("pack: could not read the asset index: %s" % exc)
        return 1
    served = [line.strip() for line in index.split("\n") if line.strip()]
    uncovered = [name for name in served if name not in names]
    if uncovered:
        print("pack: manifest does not cover every asset the dev server "
              "serves; missing %s" % ", ".join(uncovered))
        return 1
    for name in names:
        try:
            data = fetch(port, name)
        except Exception as exc:
            print("pack: fetch %s failed: %s" % (name, exc))
            return 1
        with open(os.path.join(outdir, name), "wb") as fh:
            fh.write(data)
        print("packed %s" % name)
    print("bundle complete: %d assets" % len(names))
    return 0


if __name__ == "__main__":
    sys.exit(main())

