python3 scripts/dev_server.py 5 & sleep 0.5; port=$(cat .server_ready); python3 - "$port" <<'EOF'
import sys, urllib.request
port = sys.argv[1]
for name in ("app.css", "app.js", "index.html", "logo.svg", "vendor.js"):
    for i in range(3):
        try:
            with urllib.request.urlopen("http://127.0.0.1:%s/%s" % (port, name), timeout=2) as r:
                print(name, "attempt", i, "OK", len(r.read()))
        except Exception as e:
            print(name, "attempt", i, "FAIL", type(e).__mro__[:3], e)
EOF
kill %1 2>/dev/null; rm -f .server_ready

python3 scripts/dev_server.py 7 & sleep 0.5; port=$(cat .server_ready); python3 - "$port" <<'EOF'
import sys, urllib.request
port = sys.argv[1]
# fetch sequence mimicking pack.py: index, then each asset in manifest order
for name in ("", "app.css", "app.js", "index.html", "logo.svg", "vendor.js"):
    for i in range(2):
        try:
            with urllib.request.urlopen("http://127.0.0.1:%s/%s" % (port, name), timeout=2) as r:
                print(repr(name), "attempt", i, "OK", len(r.read()))
        except Exception as e:
            print(repr(name), "attempt", i, "FAIL", type(e).__name__, e)
EOF
kill %1 2>/dev/null; rm -f .server_ready
